def _english(section):
    """Runs an English section of tech_gauges with chart, diagram and table swapped for recorders. Returns the section's
    text (its figures and tables left out) and the arguments of every call, in order."""
    calls = {'chart': [], 'diagram': [], 'table': []}
    saved = {name: getattr(tg, name) for name in calls}
    for name in calls:
        setattr(tg, name, lambda *a, _name=name, **k: calls[_name].append((a, k)) or '')
    try:
        text = section()
    finally:
        for name, fn in saved.items():
            setattr(tg, name, fn)
    return text, calls


def _tr(text, rules):
    """The Russian for an English label: the first (pattern, replacement) whose pattern matches all of it. A label no rule
    knows stops the build, so a changed English label cannot slip through untranslated."""
    if not text:
        return text
    for pat, rep in rules:
        m = re.fullmatch(pat, text)
        if m:
            return m.expand(rep)
    raise KeyError(f'no Russian text for {text!r}')


def _chart(call, rules, xlabel, ylabel, cap):
    """Draws a recorded English chart again: the same points, ranges and options, the labels in Russian."""
    args, kw = call
    series = [(_tr(s[0], rules),) + tuple(s[1:]) for s in args[0]]
    kw = dict(kw)
    for key in ('hlines', 'vlines'):
        if key in kw:
            kw[key] = [(v, _tr(t, rules)) for v, t in kw[key]]
    return chart(series, *args[1:5], xlabel, ylabel, cap, **kw)


def _rows(call, rules):
    """The rows of a recorded English table, each cell through _tr."""
    (cols, rows, *_), _ = call
    return [[_tr(c, rules) for c in r] for r in rows]


def _number(text, pattern):
    """A number the English section prints in its text, found by the words around it."""
    return re.search(pattern, text).group(1)


